SELECT ID, HighImpact, ModerateImpact, Synonymous, CADDphred 
FROM varInfo_synthetic 
WHERE gene_name = 'ABCA4' AND SIFT = 'deleterious' ORDER BY ABS(CAST(CADDphred AS REAL)) DESC LIMIT 10;

SELECT AVG(AF) AS avg_AF
FROM varInfo_synthetic
WHERE Synonymous = 'TRUE' OR ModerateImpact = 'TRUE' OR HighImpact = 'TRUE';

