SELECT SUM(CASE WHEN T1.pheno = 'CASE' THEN T2.AF ELSE 0 END) - SUM(CASE WHEN T1.pheno = 'CONTROL' THEN T2.AF ELSE 0 END) AS allele_difference
FROM pheno AS T1
JOIN varInfo AS T2 ON T1.IID = T2.VAR_id;

