SELECT VAR_id, CHROM, POS, ID, REF, ALT, QUAL, FILTER, AC, AN, AF, gene_name, HighImpact, ModerateImpact, Synonymous, CADDphred, PolyPhen, SIFT, ALS_1, ALS_2, ALS_3, ALS_4, ALS_5, Control_1, Control_2, Control_3, Control_4, Control_5
FROM varInfo_synthetic
