SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'SOD1' AND HighImpact + ModerateImpact > 0 AND (ALS_1 = 'Female' OR ALS_2 = 'Female' OR ALS_3 = 'Female' OR ALS_4 = 'Female' OR ALS_5 = 'Female');

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'TARDBP' AND SIFT = 'D';

SELECT VAR_id, CHROM, POS, ID, REF, ALT, QUAL, FILTER, AC, AN, AF, gene_name, HighImpact
FROM varInfo_synthetic
WHERE HighImpact = 'high' AND (ALS_1 >= 2 OR ALS_2 >= 2 OR ALS_3 >= 2 OR ALS_4 >= 2 OR ALS_5 >= 2);

SELECT DISTINCT v.ID, v.CHROM, v.POS, v.REF, v.ALT, v.QUAL, v.FILTER, v.AC, v.AN, v.AF, v.gene_name, v.HighImpact, v.ModerateImpact, v.Synonymous, v.CADDphred, v.PolyPhen, v.SIFT, v.ALS_1, v.ALS_2, v.ALS_3, v.ALS_4, v.ALS_5
FROM varInfo_synthetic v
WHERE (v.ALS_1 = 2 OR v.ALS_2 = 2 OR v.ALS_3 = 2 OR v.ALS_4 = 2 OR v.ALS_5 = 2) AND v.HighImpact = 1;

SELECT AVG(AF) AS avg_AF 
FROM varInfo_synthetic 
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE HighImpact = 'true' AND ALS_1 > 0;

SELECT 
    (SUM(CASE WHEN CHROM LIKE 'chr%' THEN 1 ELSE 0 END) - SUM(CASE WHEN CHROM LIKE 'control%' THEN 1 ELSE 0 END)) AS difference
FROM varInfo_synthetic;

SELECT SUM(CASE WHEN CHROM LIKE 'chr21' THEN 1 ELSE 0 END) - 
SUM(CASE WHEN CHROM LIKE 'chrX' THEN 1 ELSE 0 END) AS variant_difference
FROM varInfo_synthetic;

SELECT SUM(CASE WHEN ALS_1 > 0 THEN 1 ELSE 0 END) AS Male_Carriers, 
       SUM(CASE WHEN ALS_2 > 0 THEN 1 ELSE 0 END) AS Female_Carriers
FROM varInfo_synthetic;

SELECT VAR_id, CHROM, POS, ID, REF, ALT, QUAL, FILTER, AC, AN, AF, gene_name, HighImpact, ModerateImpact, Synonymous, CADDphred, PolyPhen, SIFT 
FROM varInfo_synthetic 
WHERE HighImpact = 1 OR ModerateImpact = 1;

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'SOD1' AND HighImpact IS NOT NULL;
